PAGE = dict(
    slug='band_y',
    title='Pane::band_y',
    signature='Pane& Pane::band_y(Range1d span, std::string label = {})',
    intro="Adds a shaded band across the plane from y = `span.low` to `span.high`, with an optional `label`. A band marks a range (an acceptable tolerance, a recession, a season) the way a [rule](rule_y.md) marks a position: it is not a trace and is not in the legend, and it takes its colours from the pane's theme. Each call adds one band; they are kept in order and listed by [`bands`](bands.md).\n\nThe span must be finite and strictly increasing (`low < high`); anything else throws `pluss::Error` and nothing is added. A band takes part in the automatic range of its axis, so one outside the data widens the axis to keep it visible. A manual range ([`y_limits`](y_limits.md)) is never changed by it: a band partly inside the range is trimmed to it, and one entirely outside is not drawn. It is drawn when the figure is rendered.",
    parameters='**span** (`Range1d`)\n    The range, `{low, high}`, in data units. Finite and strictly increasing.\n\n**label** (`std::string`, default empty)\n    Text written on the band. Empty draws no text.',
    returns='`Pane&`\n    The same pane, for chaining.',
    examples=[
        dict(id='basic', text='A shaded range. A band from y = 2 to 3 with the label `target zone`; it is stored with its axis, span and label, and the label is drawn on the band.',
             code='auto fig = studio("band_y_basic");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.band_y(Range1d{2.0, 3.0}, "target zone");\nconst auto& band = pane.bands().front();\nstd::cout << "stored: axis " << static_cast<int>(band.axis) << ", span " << band.span.low << " .. " << band.span.high << ", label \'" << band.label << "\'\\n";\nstd::cout << "label drawn: " << (fig.to_svg().find(">target zone<") != std::string::npos) << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='no_label', text='Without a label. The label is optional; the band is drawn without text and adds shapes to the figure.',
             code='auto paths = [](const std::string& svg) {\n  std::size_t n = 0;\n  for (auto at = svg.find("<path"); at != std::string::npos; at = svg.find("<path", at + 1)) ++n;\n  return n;\n};\nauto build = [&](bool with_band) {\n  auto fig = studio("band_y_nolabel");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  if (with_band) pane.band_y(Range1d{2.0, 3.0});\n  return fig.to_svg();\n};\nstd::cout << "paths without: " << paths(build(false)) << ", with: " << paths(build(true)) << "\\n";\nauto fig = studio("band_y_nolabel_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.band_y(Range1d{2.0, 3.0});\nfig.save_svg("figure.svg");'),
        dict(id='several', text='Several bands. Bands are kept in the order added and each is drawn, so a pane can show a normal range and a warning range together.',
             code='auto fig = studio("band_y_several");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.band_y(Range1d{1.0, 2.0}, "low").band_y(Range1d{2.5, 3.5}, "high");\nstd::cout << "bands: " << pane.bands().size() << ":";\nfor (const auto& b : pane.bands()) std::cout << " " << b.label << " [" << b.span.low << ", " << b.span.high << "]";\nstd::cout << "\\n";\nfig.save_svg("figure.svg");'),
        dict(id='range', text='Bands and the y range. A band far outside the data widens an automatic range so it stays visible; with a manual range the axis stays where it was set, a band partly inside is trimmed to the range, and one entirely outside is not drawn.',
             code='auto texts = [](const std::string& svg) {\n  std::string out;\n  for (std::size_t at = svg.find("<text"); at != std::string::npos; at = svg.find("<text", at + 1)) {\n    const auto gt = svg.find(\'>\', at);\n    out += svg.substr(gt + 1, svg.find("</text>", gt) - gt - 1) + " ";\n  }\n  return out;\n};\nauto build = [&](bool manual) {\n  auto fig = studio("band_y_range");\n  auto& pane = fig.pane2("p");\n  pane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\n  pane.x_tick_labels(false);\n  pane.z_tick_labels(false);\n  if (manual) pane.y_limits(Range1d{0.0, 5.0});\n  pane.band_y(Range1d{30.0, 40.0}, "far");\n  return fig.to_svg();\n};\nstd::cout << "automatic range: " << texts(build(false)) << "\\n";\nstd::cout << "manual 0 to 5:   " << texts(build(true)) << "\\n";\nauto fig = studio("band_y_range_out");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\npane.band_y(Range1d{30.0, 40.0}, "far");\nfig.save_svg("figure.svg");'),
        dict(id='invalid', text='The span must be finite and strictly increasing. A reversed span, an empty one and a NaN end each throw `pluss::Error`, and no band is added.',
             code='auto fig = studio("band_y_invalid");\nauto& pane = fig.pane2("p");\npane.trend(std::vector<double>{1, 2, 3, 4}, std::vector<double>{2, 5, 4, 3});\nconst double nan = std::numeric_limits<double>::quiet_NaN();\nconst Range1d bad[] = {{3.0, 2.0}, {2.0, 2.0}, {nan, 2.0}};\nfor (const Range1d& span : bad) {\n  try {\n    pane.band_y(span, "never");\n  } catch (const pluss::Error& e) {\n    std::cout << span.low << " .. " << span.high << ": " << e.message() << "\\n";\n  }\n}\nstd::cout << "bands added: " << pane.bands().size() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Not `noexcept`: it throws for an invalid span.',
    see=['[`Pane::rule_y`](rule_y.md): a single position.', '[`Pane::bands`](bands.md): the bands of the pane.', '[`Pane::band_x`](band_x.md): the same for the x axis.', '[`Pane::band_z`](band_z.md): the same for the z axis.'],
)
